        const R = st.r + (0.023 + (opt.rootClear ?? 0.006)) * k, zo = st.zOff || 0;
        const m = (Math.abs(x) / R) ** n + (Math.abs(z - zo) / (R * st.zs)) ** n;
        if (m >= 1) return [x, z];
